const dateInput = $json.body?.date;
const timeInput = $json.body?.time;

if (!dateInput) {
  throw new Error("Date is missing from the webhook request.");
}

if (!timeInput) {
  throw new Error("Time is missing from the webhook request.");
}

const currentYear = new Date().getFullYear();

// Remove ordinal suffixes:
// 1st September → 1 September
// September 1st → September 1
let cleanDate = String(dateInput)
  .trim()
  .replace(/(\d+)(st|nd|rd|th)/gi, '$1');

// Parse date
let parsedDate = new Date(`${cleanDate}, ${currentYear}`);

if (isNaN(parsedDate.getTime())) {
  throw new Error(`Invalid date received: ${dateInput}`);
}

// Convert time
function convertTime(timeString) {
  const cleanTime = String(timeString).trim();

  const match = cleanTime.match(
    /^(\d{1,2})(?::(\d{2}))?\s*(AM|PM)$/i
  );

  if (!match) {
    throw new Error(`Invalid time received: ${timeString}`);
  }

  let hour = parseInt(match[1], 10);
  const minute = match[2] || '00';
  const period = match[3].toUpperCase();

  if (hour < 1 || hour > 12) {
    throw new Error(`Invalid hour received: ${timeString}`);
  }

  if (period === 'PM' && hour !== 12) {
    hour += 12;
  }

  if (period === 'AM' && hour === 12) {
    hour = 0;
  }

  return `${String(hour).padStart(2, '0')}:${minute}`;
}

const normalizedTime = convertTime(timeInput);

const year = parsedDate.getFullYear();
const month = String(parsedDate.getMonth() + 1).padStart(2, '0');
const day = String(parsedDate.getDate()).padStart(2, '0');

const normalizedDate = `${year}-${month}-${day}`;

const startDateTime = `${normalizedDate}T${normalizedTime}:00`;

return {
  json: {
    ...$json,

    normalized_date: normalizedDate,

    normalized_time: normalizedTime,

    start_datetime: startDateTime
  }
};
